css:
.platesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #3a2c1e;
    background: linear-gradient(160deg, #f7f1e6 0%, #efe6d4 100%);
    border-radius: 18px;
}

.platesim-container * {
    box-sizing: border-box;
}

.platesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #5a3a22 0%, #8a4a2c 55%, #b5622f 100%);
    color: #fbf3e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(90, 58, 34, 0.30);
}

.platesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.platesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f2d9b8;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.platesim-subtitle {
    margin: 0 auto;
    max-width: 790px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f4e6d3;
}

.platesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b4a2c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.platesim-period-counter #currentDay,
.platesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #5a3a22;
}

.platesim-round-name {
    background: #e3d3b6;
    color: #5a3a22;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.platesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c3a1e;
    background: #f6ddcf;
    padding: 4px 12px;
    border-radius: 999px;
}

.platesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.platesim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6d8bf;
    box-shadow: 0 4px 14px rgba(90, 58, 34, 0.07);
    border-top: 4px solid #8a4a2c;
}

.platesim-card-margin { border-top-color: #9c6b1e; }
.platesim-card-sustain { border-top-color: #4f7a3a; }
.platesim-card-novelty { border-top-color: #b5622f; }
.platesim-card-waste { border-top-color: #7a5a3a; }

.platesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7556;
}

.platesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #5a3a22;
}

.platesim-card-margin .platesim-value { color: #9c6b1e; }
.platesim-card-sustain .platesim-value { color: #4f7a3a; }
.platesim-card-novelty .platesim-value { color: #b5622f; }
.platesim-card-waste .platesim-value { color: #7a5a3a; }

.platesim-sublabel {
    font-size: 0.76rem;
    color: #9b8869;
    line-height: 1.35;
}

.platesim-margin-fail .platesim-value { color: #c0392b; }
.platesim-margin-ok .platesim-value { color: #4f7a3a; }
.platesim-waste-fail .platesim-value { color: #c0392b; }
.platesim-waste-ok .platesim-value { color: #4f7a3a; }
.platesim-novelty-ok .platesim-value { color: #4f7a3a; }

.platesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #5a3a22;
    color: #f7ecdb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.platesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.platesim-budget-over #budgetDisplay {
    color: #ffc7b0;
}

.platesim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #4f7a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(90, 58, 34, 0.06);
}

.platesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.platesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #5a3a22;
    margin-bottom: 6px;
}

.platesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3826;
}

.platesim-briefing-text strong { color: #4f7a3a; }
.platesim-briefing-text em { color: #9c3a1e; font-style: italic; }

.platesim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6d8bf;
    box-shadow: 0 4px 14px rgba(90, 58, 34, 0.07);
}

.platesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #5a3a22;
    border-bottom: 2px solid #efe6d4;
    padding-bottom: 8px;
}

.platesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5a4128;
    margin: 14px 0 6px;
}

.platesim-container select,
.platesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c4a0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf8ee;
    color: #3a2c1e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.platesim-container select:focus,
.platesim-container input[type="number"]:focus {
    outline: none;
    border-color: #8a4a2c;
    box-shadow: 0 0 0 3px rgba(138, 74, 44, 0.15);
}

.platesim-container select option {
    background-color: #fffdf8;
    color: #3a2c1e;
}

.platesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4f7a3a;
}

.platesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b4a2c;
    margin-top: 4px;
}

.platesim-range-readout span:last-child {
    color: #4f7a3a;
    font-weight: 800;
}

.platesim-hint {
    font-size: 0.8rem;
    color: #9b8869;
    margin-top: 4px;
    line-height: 1.4;
}

.platesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.platesim-container .btn-primary {
    background: linear-gradient(135deg, #4f7a3a 0%, #8a4a2c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(79, 122, 58, 0.28);
}

.platesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.platesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c4a0;
    color: #8a7556;
}

.platesim-coach {
    background: #3a2c1e;
    color: #f3e7d4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(58, 44, 30, 0.24);
}

.platesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d9b88a;
    margin-bottom: 8px;
}

.platesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.platesim-coach-body strong { color: #a8d49a; }
.platesim-coach-body em { color: #f0b89a; font-style: italic; }

.platesim-history,
.platesim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6d8bf;
    box-shadow: 0 4px 14px rgba(90, 58, 34, 0.07);
}

.platesim-history h3,
.platesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #5a3a22;
}

.platesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3826;
}

.platesim-container table#usfHistoryTable th {
    background: #f0e6d2;
    color: #5a3a22;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d0b2;
}

.platesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e8d6;
}

.platesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6ec;
}

.platesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .platesim-container {
        padding: 14px;
    }
    .platesim-header h1 {
        font-size: 1.7rem;
    }
    .platesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .platesim-value {
        font-size: 2rem;
    }
    .platesim-clock {
        margin-left: 0;
    }
    .platesim-period-counter {
        font-size: 0.88rem;
    }
    .platesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .platesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (platesim) ---- */
.platesim-completion { padding: 8px 4px 4px; }
.platesim-cm-head { text-align: center; margin-bottom: 16px; }
.platesim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #6a8a3a; }
.platesim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #90a86a; }
.platesim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #33301f; }
.platesim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.platesim-cm-yes { background: rgba(106,138,58,0.16); color: #55772c; border: 1px solid rgba(106,138,58,0.55); }
.platesim-cm-no { background: rgba(176,80,42,0.12); color: #a5482a; border: 1px solid rgba(176,80,42,0.45); }
.platesim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.platesim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(106,138,58,0.09); border: 1px solid rgba(106,138,58,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.platesim-cm-mv { display: block; font-size: 1.35rem; font-weight: 800; color: #5a7730; }
.platesim-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #756a4f; text-transform: uppercase; letter-spacing: 0.03em; }
.platesim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #33301f; }
.platesim-cm-insights { margin: 0; padding-left: 20px; }
.platesim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #43402d; }

