(function() {
    'use strict';

    class PlateAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Plate to Plan`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Trattoria Radici).
            this.START_FOODCOST = 41;     // draft creative menu food cost %
            this.BASELINE_FOODCOST = 33;  // pre-relaunch baseline
            this.MARGIN_FLOOR = 35;       // food-cost ceiling the controller defends
            this.START_SUSTAIN = 30;      // regenerative integrity, low headroom
            this.START_NOVELTY = 55;      // craveable delight (NOT the 8.4 panel novelty)
            this.NOVELTY_TARGET = 80;     // target ≥80
            this.START_WASTE = 9.0;       // % of food purchases
            this.WASTE_TARGET = 4.0;      // promise ≤4%
            this.BUDGET_CAP = 120;        // relaunch budget, €k
            this.SUPPLY_CEILING = 60;     // farms guarantee ~60% of forecast volume
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    foodcost: this.START_FOODCOST,
                    sustain: this.START_SUSTAIN,
                    novelty: this.START_NOVELTY,
                    waste: this.START_WASTE,
                    reliability: 50,        // supply reliability vs the 60% ceiling
                    budgetUsed: 0,
                    greenwashing: false,
                    overpriced: false,
                    foodcostHistory: [this.START_FOODCOST],
                    sustainHistory: [this.START_SUSTAIN],
                    noveltyHistory: [this.START_NOVELTY],
                    wasteHistory: [this.START_WASTE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded middling/neutral — a click-through must NOT auto-win.
                state.decisions = {
                    tension: `costnovelty`,
                    split: `balanced`,
                    diagnosis: 55,
                    sourcing: `commit`,
                    share: 60,
                    contingency: `flexcourse`,
                    farmspend: 25,
                    engineering: `rebalance`,
                    rootleaf: 40,
                    joyless: `rework`,
                    check: 122,
                    flex: `anchorflex`,
                    story: `woven`,
                    model: `operating`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const tn = document.getElementById(`tensionInput`);
                const sp = document.getElementById(`splitInput`);
                const dg = document.getElementById(`diagnosisInput`);
                if (tn) decisions.tension = tn.value;
                if (sp) decisions.split = sp.value;
                if (dg) decisions.diagnosis = parseInt(dg.value, 10);
                if (!Number.isFinite(decisions.diagnosis) || decisions.diagnosis < 0 || decisions.diagnosis > 100) {
                    warn(`warn_diagnosis_range`); return false;
                }
            } else if (round === 2) {
                const so = document.getElementById(`sourcingInput`);
                const sh = document.getElementById(`shareInput`);
                const co = document.getElementById(`contingencyInput`);
                const fs = document.getElementById(`farmspendInput`);
                if (so) decisions.sourcing = so.value;
                if (sh) decisions.share = parseInt(sh.value, 10);
                if (co) decisions.contingency = co.value;
                if (fs) decisions.farmspend = parseFloat(fs.value);
                if (!Number.isFinite(decisions.share) || decisions.share < 20 || decisions.share > 100) {
                    warn(`warn_share_range`); return false;
                }
                if (!Number.isFinite(decisions.farmspend) || decisions.farmspend < 0 || decisions.farmspend > 60) {
                    warn(`warn_farmspend_range`); return false;
                }
            } else if (round === 3) {
                const en = document.getElementById(`engineeringInput`);
                const rl = document.getElementById(`rootleafInput`);
                const jo = document.getElementById(`joylessInput`);
                const ch = document.getElementById(`checkInput`);
                if (en) decisions.engineering = en.value;
                if (rl) decisions.rootleaf = parseInt(rl.value, 10);
                if (jo) decisions.joyless = jo.value;
                if (ch) decisions.check = parseFloat(ch.value);
                if (!Number.isFinite(decisions.rootleaf) || decisions.rootleaf < 0 || decisions.rootleaf > 100) {
                    warn(`warn_rootleaf_range`); return false;
                }
                if (!Number.isFinite(decisions.check) || decisions.check < 115 || decisions.check > 160) {
                    warn(`warn_check_range`); return false;
                }
            } else if (round === 4) {
                const fl = document.getElementById(`flexInput`);
                const st = document.getElementById(`storyInput`);
                const mo = document.getElementById(`modelInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fl) decisions.flex = fl.value;
                if (st) decisions.story = st.value;
                if (mo) decisions.model = mo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas accumulate into the four KPIs. foodcostDelta is in % POINTS
            // (negative = improvement, pulling toward the 35% floor).
            let foodcostDelta = 0, sustainDelta = 0, noveltyDelta = 0, wasteDelta = 0, reliabilityDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the pantry: locate where creativity and economics collide.
                switch (d.tension) {
                    case `costnovelty`:  // concept-correct: flag dishes that cost without adding novelty
                        foodcostDelta -= 1.5; noveltyDelta += 4; sustainDelta += 3; coachKey = `coach_r1_costnovelty`; break;
                    case `allcreative`:  // Common Error 1: creativity over economics
                        foodcostDelta += 1.0; noveltyDelta += 1; sustainDelta -= 2; coachKey = `coach_r1_allcreative`; break;
                    case `cutregen`:     // strips the regenerative soul to protect margin
                        foodcostDelta -= 2.0; sustainDelta -= 12; noveltyDelta -= 4; coachKey = `coach_r1_cutregen`; break;
                    case `priceonly`:    // Common Error 6: pricing as the only answer
                        noveltyDelta -= 3; sustainDelta -= 1; coachKey = `coach_r1_priceonly`; break;
                }

                // Leone's lens: improvise volatile supply, structure the anchor margin dishes.
                switch (d.split) {
                    case `balanced`:   // improvisation within structure — concept-correct
                        foodcostDelta -= 1.0; reliabilityDelta += 14; sustainDelta += 4; noveltyDelta += 3;
                        if (d.tension === `costnovelty`) coachKey = `coach_r1_sharp`;
                        break;
                    case `allfixed`:   // promises consistency the harvest can't deliver
                        reliabilityDelta -= 20; noveltyDelta -= 2; coachKey = `coach_r1_allfixed`; break;
                    case `allimprov`:  // pure spontaneity, no structure — chaos, no margin scaffold
                        foodcostDelta += 1.5; reliabilityDelta -= 6; sustainDelta += 2; coachKey = `coach_r1_allimprov`; break;
                }

                // Diagnosis depth: a rigorous dish-by-dish tension map de-risks every later round.
                if (d.diagnosis >= 70) { foodcostDelta -= 1.0; noveltyDelta += 3; sustainDelta += 3; }
                else if (d.diagnosis <= 30) { noveltyDelta -= 3; sustainDelta -= 2; coachKey = `coach_r1_shallow`; }

                summaryKey = (d.tension === `costnovelty` && d.split === `balanced`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Source the regenerative menu honestly under the 60% ceiling.
                switch (d.sourcing) {
                    case `commit`:        // full story value, higher cost, lower volume
                        foodcostDelta += 2.0; sustainDelta += 16; reliabilityDelta -= 6; coachKey = `coach_r2_commit`; break;
                    case `blend_open`:    // declared blend — honest middle path, concept-correct
                        foodcostDelta -= 1.0; sustainDelta += 9; reliabilityDelta += 6; coachKey = `coach_r2_blendopen`; break;
                    case `blend_hidden`:  // Common Error 2: quiet greenwashing — audited by the jury
                        foodcostDelta -= 3.0; sustainDelta -= 18; coachKey = `coach_r2_blendhidden`;
                        if (d.share >= 70) ds.greenwashing = true; // big claim + hidden conventional = lie
                        break;
                    case `substitute`:    // abundant local alternatives — cheap, modest story
                        foodcostDelta -= 2.5; sustainDelta += 2; noveltyDelta -= 2; reliabilityDelta += 8; coachKey = `coach_r2_substitute`; break;
                }

                // Claimed regenerative share: honesty depends on whether the kitchen can back it.
                // A high claim is only credible if you actually commit or openly blend.
                const backed = (d.sourcing === `commit` || d.sourcing === `blend_open`);
                if (d.share >= 80) {
                    if (backed) { sustainDelta += 6; }
                    else { sustainDelta -= 10; foodcostDelta += 0.5; ds.greenwashing = true; coachKey = `coach_r2_overclaim`; }
                } else if (d.share <= 35) {
                    sustainDelta -= 4; // under-claiming wastes the regenerative positioning
                }

                // Contingency for the heirloom bean (designing for the 60% ceiling).
                switch (d.contingency) {
                    case `flexcourse`:  // "what the land gives" — concept-correct
                        reliabilityDelta += 14; noveltyDelta += 3; sustainDelta += 4; break;
                    case `fixedprint`:  // print & hope — Common Error 3
                        reliabilityDelta -= 26; noveltyDelta -= 3; coachKey = `coach_r2_fixedprint`; break;
                    case `lastminute`:  // buy conventional last minute — breaks the claim
                        reliabilityDelta += 2; sustainDelta -= 8; coachKey = `coach_r2_lastminute`;
                        if (d.share >= 70) ds.greenwashing = true;
                        break;
                }

                // Farm spend secures weekly volume and stabilises reliability (diminishing returns).
                spend += d.farmspend;
                if (d.farmspend >= 30) { reliabilityDelta += 14; sustainDelta += 4; foodcostDelta -= 1.0; }
                else if (d.farmspend >= 15) { reliabilityDelta += 8; sustainDelta += 2; }
                else { reliabilityDelta -= 6; coachKey = `coach_r2_nofarmspend`; }

                summaryKey = (d.sourcing === `blend_open` && d.contingency === `flexcourse` && !ds.greenwashing) ? `sum_r2_good`
                    : (ds.greenwashing ? `sum_r2_greenwash` : `sum_r2_weak`);
            } else if (round === 3) {
                // Engineer the menu inside the floor without killing novelty or the waste target.
                switch (d.engineering) {
                    case `rebalance`:  // stars/plowhorses/puzzles/dogs grid — concept-correct
                        foodcostDelta -= 3.0; noveltyDelta += 4; sustainDelta += 3; wasteDelta -= 0.8; coachKey = `coach_r3_rebalance`; break;
                    case `keepall`:    // engineering kills artistry — margin never lands
                        foodcostDelta += 1.5; noveltyDelta += 2; coachKey = `coach_r3_keepall`; break;
                    case `marginonly`: // cheapest dishes only — Common Error (virtue & novelty gutted)
                        foodcostDelta -= 4.0; noveltyDelta -= 14; sustainDelta -= 8; coachKey = `coach_r3_marginonly`; break;
                }

                // Root-to-leaf cooking converts the 9% waste into plated value AND cuts cost.
                const rl = d.rootleaf;
                wasteDelta -= (rl / 100) * 7.0;          // up to -7.0 pts toward the ≤4% target
                foodcostDelta -= (rl / 100) * 2.5;        // trim becomes stock/garnish, lowers food cost
                if (rl >= 60) { sustainDelta += 8; noveltyDelta += 2; coachKey = (d.engineering === `rebalance`) ? `coach_r3_engineered` : `coach_r3_rootleaf`; }
                else if (rl <= 20) { sustainDelta -= 4; coachKey = `coach_r3_wasteignored`; }

                // The two "joyless" dishes — virtue must clear the desirability bar.
                switch (d.joyless) {
                    case `rework`:  // craveable AND regenerative — concept-correct
                        noveltyDelta += 7; sustainDelta += 4; foodcostDelta += 0.5; break;
                    case `keep`:    // Common Error 5: virtue over desirability
                        noveltyDelta -= 14; sustainDelta += 3; coachKey = `coach_r3_keepjoyless`; break;
                    case `cut`:     // cut & replace with conventional crowd-pleasers
                        noveltyDelta += 3; sustainDelta -= 12; foodcostDelta -= 1.0; coachKey = `coach_r3_cutjoyless`; break;
                }

                // Average check: price can carry some cost, not all of it (Common Error 6).
                const ch = d.check;
                const lift = ch - 115;
                foodcostDelta -= Math.min(lift, 12) * 0.18; // modest cost relief from price up to ~+12
                if (ch >= 140) { noveltyDelta -= 18; ds.overpriced = true; coachKey = `coach_r3_overpriced`; }
                else if (ch >= 130) { noveltyDelta -= 8; }

                summaryKey = (d.engineering === `rebalance` && d.joyless === `rework` && rl >= 60 && !ds.overpriced) ? `sum_r3_good`
                    : (ds.overpriced ? `sum_r3_overpriced` : `sum_r3_weak`);
            } else if (round === 4) {
                // Launch & defend a repeatable 12-month operating model.
                switch (d.flex) {
                    case `anchorflex`:  // fixed anchors + weekly flex — concept-correct
                        reliabilityDelta += 12; sustainDelta += 6; noveltyDelta += 3; foodcostDelta -= 1.0; coachKey = `coach_r4_anchorflex`; break;
                    case `fixedmenu`:   // fixed print every week — Common Error 3 again
                        reliabilityDelta -= 26; sustainDelta -= 4; coachKey = `coach_r4_fixedmenu`; break;
                    case `totalimprov`: // no anchors — margin scaffold gone
                        foodcostDelta += 1.5; reliabilityDelta -= 4; noveltyDelta += 2; coachKey = `coach_r4_totalimprov`; break;
                }

                // Front-of-house storytelling: the food leads, the story supports.
                switch (d.story) {
                    case `woven`:    noveltyDelta += 6; sustainDelta += 5; break;
                    case `lecture`:  noveltyDelta -= 9; sustainDelta += 1; coachKey = `coach_r4_lecture`; break;
                    case `silent`:   sustainDelta -= 6; noveltyDelta += 1; coachKey = `coach_r4_silent`; break;
                }

                // What you present to the critic & jury.
                switch (d.model) {
                    case `operating`:   // repeatable 12-month model, all 4 KPIs owned — concept-correct
                        sustainDelta += 12; noveltyDelta += 3; reliabilityDelta += 6;
                        if (d.flex === `anchorflex` && d.story === `woven`) coachKey = `coach_r4_operating`;
                        break;
                    case `event`:       // one-night dazzle — Common Error
                        sustainDelta -= 12; noveltyDelta += 4; coachKey = `coach_r4_event`; break;
                    case `margincase`:  // downplay regeneration — undermines the public claim
                        sustainDelta -= 16; coachKey = `coach_r4_margincase`; break;
                }

                // Conviction nudges novelty (the team's belief that constraints sharpened creativity).
                noveltyDelta += Math.round((d.conviction - 60) / 12);
            }

            // Budget accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));

            // Apply deltas with bounds. Food cost floored at a hard-to-reach 30 (better than the
            // 33 baseline) so the 35 floor stays a genuine achievement, not auto-cleared.
            ds.foodcost = Math.max(30, Math.min(45, Math.round((ds.foodcost + foodcostDelta) * 10) / 10));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustainDelta));
            ds.novelty = Math.max(0, Math.min(100, ds.novelty + noveltyDelta));
            ds.waste = Math.max(1.5, Math.min(12, Math.round((ds.waste + wasteDelta) * 10) / 10));
            ds.reliability = Math.max(0, Math.min(100, ds.reliability + reliabilityDelta));

            ds.foodcostHistory.push(ds.foodcost);
            ds.sustainHistory.push(Math.round(ds.sustain));
            ds.noveltyHistory.push(Math.round(ds.novelty));
            ds.wasteHistory.push(ds.waste);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            if (summaryKey === `sum_default` && round === 4) {
                summaryKey = (d.flex === `anchorflex` && d.model === `operating` && d.story === `woven`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                foodcost: ds.foodcost,
                foodcostDelta: Math.round(foodcostDelta * 10) / 10,
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustainDelta),
                novelty: Math.round(ds.novelty),
                noveltyDelta: Math.round(noveltyDelta),
                waste: ds.waste,
                reliability: Math.round(ds.reliability),
                budgetUsed: ds.budgetUsed,
                greenwashing: ds.greenwashing,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

