        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula (incl. greenwash -25 penalty) copied VERBATIM from v1.0.0.
        _composite(ds) {
            const foodcost = Math.round(ds.foodcost * 10) / 10;
            const sustain = Math.round(ds.sustain);
            const novelty = Math.round(ds.novelty);
            const waste = Math.round(ds.waste * 10) / 10;
            const reliability = Math.round(ds.reliability);
            const marginScore = Math.max(0, Math.min(100, (45 - foodcost) / (45 - 30) * 100));
            const wasteScore = Math.max(0, Math.min(100, (12 - waste) / (12 - 1.5) * 100));
            let composite = Math.round(marginScore * 0.25 + sustain * 0.22 + novelty * 0.22 + wasteScore * 0.16 + reliability * 0.15);
            if (ds.greenwashing) composite = Math.max(0, composite - 25);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="platesim-cm-badge platesim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="platesim-cm-badge platesim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.greenwashing) failBadge += ` <span class="platesim-cm-badge platesim-cm-no">` + T(`cm_greenwash`) + `</span>`;
            if (!s.marginOk) failBadge += ` <span class="platesim-cm-badge platesim-cm-no">` + T(`cm_overfloor`) + `</span>`;
            if (s.marginOk && !s.reliabilityOk) failBadge += ` <span class="platesim-cm-badge platesim-cm-no">` + T(`cm_unreliable`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="platesim-cm-metric"><span class="platesim-cm-mv">` + Number(s.foodcost || 0).toFixed(1) + `%</span><span class="platesim-cm-ml">` + T(`cm_m_foodcost`) + `</span></div>`
                + `<div class="platesim-cm-metric"><span class="platesim-cm-mv">` + Math.round(s.sustain || 0) + `</span><span class="platesim-cm-ml">` + T(`cm_m_sustain`) + `</span></div>`
                + `<div class="platesim-cm-metric"><span class="platesim-cm-mv">` + Math.round(s.novelty || 0) + `</span><span class="platesim-cm-ml">` + T(`cm_m_novelty`) + `</span></div>`
                + `<div class="platesim-cm-metric"><span class="platesim-cm-mv">` + Number(s.waste || 0).toFixed(1) + `%</span><span class="platesim-cm-ml">` + T(`cm_m_waste`) + `</span></div>`;
            return ``
                + `<div class="platesim-completion">`
                +   `<div class="platesim-cm-head">`
                +     `<div class="platesim-cm-score">` + score + `<span class="platesim-cm-score-max">/100</span></div>`
                +     `<div class="platesim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="platesim-cm-metrics">` + metrics + `</div>`
                +   `<div class="platesim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="platesim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const foodcost = Math.round(ds.foodcost * 10) / 10;
            const sustain = Math.round(ds.sustain);
            const novelty = Math.round(ds.novelty);
            const waste = Math.round(ds.waste * 10) / 10;
            const reliability = Math.round(ds.reliability);

            const marginOk = foodcost <= this.MARGIN_FLOOR;
            const wasteOk = waste <= this.WASTE_TARGET;
            const noveltyOk = novelty >= this.NOVELTY_TARGET;
            const reliabilityOk = reliability >= 80; // can the regenerative menu actually flex week to week?
            const greenwash = ds.greenwashing;

            // Composite 0–100: margin (lower better), sustainability, novelty, waste (lower better),
            // and supply reliability — a menu that can't be supplied is not a repeatable model.
            const composite = this._composite(ds);

            let performanceKey = `grade_bankrupt`;
            if (greenwash) performanceKey = `grade_greenwash`;
            else if (marginOk && wasteOk && noveltyOk && reliabilityOk && sustain >= 65 && composite >= 85) performanceKey = `grade_regenerative`;
            else if (marginOk && wasteOk && noveltyOk) performanceKey = `grade_stardefended`;
            else if (marginOk && (wasteOk || noveltyOk)) performanceKey = `grade_insidefloor`;
            else if (foodcost <= 37) performanceKey = `grade_closefloor`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (greenwash) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (performanceKey === `grade_regenerative`) insights.push(window.mySimulation.t(`insight_repeatable`));
            else if (marginOk && wasteOk && noveltyOk) insights.push(window.mySimulation.t(`insight_balanced`));
            else if (marginOk) insights.push(window.mySimulation.t(`insight_marginonly`));
            else insights.push(window.mySimulation.t(`insight_overcost`));

            if (!marginOk) insights.push(window.mySimulation.t(`insight_floor`));
            if (!wasteOk) insights.push(window.mySimulation.t(`insight_waste`));
            if (!noveltyOk) insights.push(window.mySimulation.t(`insight_novelty`));
            if (ds.reliability < 45) insights.push(window.mySimulation.t(`insight_reliability`));

            return {
                foodcost: foodcost,
                sustain: sustain,
                novelty: novelty,
                waste: waste,
                reliability: reliability,
                marginOk: marginOk,
                wasteOk: wasteOk,
                noveltyOk: noveltyOk,
                reliabilityOk: reliabilityOk,
                greenwashing: greenwash,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (!greenwash && marginOk && wasteOk && noveltyOk && reliabilityOk && sustain >= 65 && composite >= 85),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenwashing) return window.mySimulation.t(`hint_greenwash`);
            if (state.currentPeriod >= 2 && ds.foodcost > 39) return window.mySimulation.t(`hint_cost`);
            if (state.currentPeriod >= 3 && ds.waste > this.WASTE_TARGET + 2) return window.mySimulation.t(`hint_waste`);
            if (state.currentPeriod >= 3 && ds.novelty < 60) return window.mySimulation.t(`hint_novelty`);
            if (ds.reliability < 40) return window.mySimulation.t(`hint_reliability`);
            if (ds.foodcost <= this.MARGIN_FLOOR && ds.waste <= this.WASTE_TARGET && ds.novelty >= this.NOVELTY_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

